import random, sys, json
from harness import *
import importlib
gw2 = gw

random.seed(1234)
base_texts = [
    req(),
    req(frm=['"A, vis\\"it" <SIP:%65MBER@STUDIO.TEST.>'], tag=None, privacy="id",
        extra=["P-Asserted-Identity: <sip:ember@studio.test>, <tel:+12025550121>",
               "Remote-Party-ID: <sip:ember@studio.test>",
               "Via: SIP/2.0/UDP 10.0.0.1;branch=z9hG4bK-x",
               "Authorization: Basic [REDACTED:TOKEN]"], body="a\r\n\r\nb\tc"),
    req(method="INVITE", cseq="21 INVITE", ctype=None, body=""),
]
alpha = list("abcXYZ019 \t\r\n:;,<>\"\\%@+.!~*'()_`-|/?=[]{}&^$#") + ["\x00","\x7f","\xc3"]

def mutate(t):
    t = list(t)
    for _ in range(random.randint(1,4)):
        op = random.choice("idsr")
        if not t: break
        i = random.randrange(len(t))
        if op == "i": t.insert(i, random.choice(alpha))
        elif op == "d": del t[i]
        elif op == "s": t[i] = random.choice(alpha)
        else:
            j = random.randrange(len(t))
            t[i], t[j] = t[j], t[i]
    return "".join(t)

internal = 0
counts = {}
for n in range(60000):
    t = mutate(random.choice(base_texts))
    job = {"gateway":"edge","ingress":{"kind":"local","subject":"session-k"},"trusted_out":random.choice([True,False]),"raw":t}
    batch = json.loads(json.dumps(BASE)); batch["jobs"]=[job]
    # call internals directly to detect non-Reject exceptions
    try:
        policy = gw2.Policy(batch["directory"], batch["accounts"], batch["gateways"])
        r = gw2.run_job(job, policy, [])
        counts["accept"] = counts.get("accept",0)+1
        # re-parse our own wire: it must always be syntactically valid
        try:
            gw2.parse_request(r["wire"])
        except Exception as e:
            print("WIRE NOT REPARSEABLE", repr(e), repr(r["wire"])[:400]); internal += 1
    except gw2.Reject as e:
        counts[e.reason] = counts.get(e.reason,0)+1
    except RecursionError:
        print("RECURSION"); internal += 1; break
    except Exception as e:
        internal += 1
        if internal < 12:
            print("INTERNAL", type(e).__name__, e, repr(t)[:300])
print(counts, "internal errors:", internal)
PYEOF
